var C = ARISTO.colors;
var startIn = document.getElementById('start');
var stopIn = document.getElementById('stop');
var stepIn = document.getElementById('step');
var playBtn = document.getElementById('play');

var reduceMotion = (typeof matchMedia === 'function') && matchMedia('(prefers-reduced-motion: reduce)').matches;

var values = [];
var visibleCount = 0; // how many dots are currently shown (for animation)
var animId = null;
var playing = false;

function computeValues() {
  var start = +startIn.value;
  var stop = +stopIn.value;
  var step = +stepIn.value;
  if (step < 1) step = 1;
  var vals = [];
  if (start < stop) {
    for (var v = start; v < stop; v += step) {
      vals.push(v);
      if (vals.length > 200) break;
    }
  }
  return vals;
}

var MIN = 0, MAX = 20;

var plot = ARISTO.canvas(document.getElementById('plot'), function (ctx, w, h) {
  var start = +startIn.value;
  var stop = +stopIn.value;
  var step = +stepIn.value;
  var pad = 20;
  var usableW = w - pad * 2;
  var oy = h * 0.55;

  function X(n) { return pad + (n - MIN) / (MAX - MIN) * usableW; }

  // baseline
  ctx.strokeStyle = C.muted;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(X(MIN), oy);
  ctx.lineTo(X(MAX), oy);
  ctx.stroke();

  // tick marks every 2 units, labels every 4
  ctx.fillStyle = C.muted;
  ctx.font = '12px system-ui, sans-serif';
  ctx.textAlign = 'center';
  for (var n = MIN; n <= MAX; n += 2) {
    var x = X(n);
    ctx.beginPath();
    ctx.moveTo(x, oy - 5);
    ctx.lineTo(x, oy + 5);
    ctx.stroke();
    if (n % 4 === 0) {
      ctx.fillText(String(n), x, oy + 20);
    }
  }

  // stop boundary line
  var stopX = X(stop);
  ctx.strokeStyle = C.danger;
  ctx.lineWidth = 2;
  ctx.setLineDash([4, 4]);
  ctx.beginPath();
  ctx.moveTo(stopX, oy - 28);
  ctx.lineTo(stopX, oy + 28);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.danger;
  ctx.font = '600 12px system-ui, sans-serif';
  ctx.fillText('stop', stopX, oy - 34);

  // dots for produced values
  var shown = Math.min(visibleCount, values.length);
  for (var i = 0; i < values.length; i++) {
    var val = values[i];
    var x2 = X(val);
    var isShown = i < shown;
    var isLast = i === shown - 1;
    ctx.beginPath();
    ctx.arc(x2, oy, isLast ? 8 : 6, 0, Math.PI * 2);
    ctx.fillStyle = isShown ? (isLast ? C.accentText : C.accent) : C.sunk;
    ctx.globalAlpha = isShown ? 1 : 0.3;
    ctx.fill();
    ctx.globalAlpha = 1;
    if (isShown) {
      ctx.fillStyle = C.ink;
      ctx.font = '12px system-ui, sans-serif';
      ctx.fillText(String(val), x2, oy - 14);
    }
  }
}, 0.3);

function fmt() {
  var start = +startIn.value;
  var stop = +stopIn.value;
  var step = +stepIn.value;
  document.getElementById('startv').textContent = String(start);
  document.getElementById('stopv').textContent = String(stop);
  document.getElementById('stepv').textContent = String(step);
  document.getElementById('code').textContent = 'range(' + start + ', ' + stop + ', ' + step + ')';
  var shown = Math.min(visibleCount, values.length);
  var shownVals = values.slice(0, shown);
  document.getElementById('list').textContent = '[' + shownVals.join(', ') + ']' +
    (shown < values.length ? ' ...' : '');
}

function stopAnim() {
  playing = false;
  if (animId !== null) { cancelAnimationFrame(animId); animId = null; }
  playBtn.textContent = 'Play dots';
}

function rebuild(startAnimated) {
  stopAnim();
  values = computeValues();
  visibleCount = values.length; // default: show all immediately
  fmt();
  plot.redraw();
}

var lastTime = 0;
var stepInterval = 450;

function tick(ts) {
  if (!lastTime) lastTime = ts;
  if (ts - lastTime >= stepInterval) {
    lastTime = ts;
    visibleCount++;
    fmt();
    plot.redraw();
    if (visibleCount >= values.length) {
      stopAnim();
      return;
    }
  }
  animId = requestAnimationFrame(tick);
}

function startPlay() {
  if (values.length === 0) return;
  playing = true;
  visibleCount = 0;
  lastTime = 0;
  playBtn.textContent = 'Pause';
  fmt();
  plot.redraw();
  animId = requestAnimationFrame(tick);
}

playBtn.addEventListener('click', function () {
  if (playing) {
    stopAnim();
  } else {
    startPlay();
  }
});

[startIn, stopIn, stepIn].forEach(function (el) {
  el.addEventListener('input', function () { rebuild(); });
});

rebuild();
if (reduceMotion) {
  // ensure fully visible, no autoplay
  visibleCount = values.length;
  fmt();
  plot.redraw();
}
